(function(){
  'use strict';
  window.WBDistillUI=function(ctx,helpers){
    const {esc:e,icon,badge,heading,modal,toast}=ctx;let filter='全部';
    const labels={case:'真实记录案例',method:'可复用方法',opportunity:'待验证内容方向'};
    const cards=()=>helpers.getLibrary().distillations||[];
    function cardHTML(c){return `<article class="distill-card"><div class="distill-card-labels">${badge(labels[c.kind],c.kind==='case'?'teal':c.kind==='method'?'blue':'amber')}${c.featured?badge('先看这张','blue'):''}</div><button class="distill-title" data-action="distill-card" data-id="${e(c.id)}">${e(c.title)}${icon('arrow-up-right')}</button><p>${e(c.summary)}</p><div class="distill-when"><strong>什么时候用</strong><span>${e(c.whenToUse)}</span></div><div class="distill-card-foot"><span>${c.evidence.length} 处引用 · ${c.steps.length} 步</span><button class="small-button" data-action="distill-card" data-id="${e(c.id)}">查看步骤与检查</button></div></article>`;}
    function render(){const items=cards().filter(c=>filter==='全部'||filter==='真实案例'&&c.kind==='case'||filter==='方法模板'&&c.kind==='method'||filter==='内容方向'&&c.kind==='opportunity');return `<div class="distill-intro"><div><h2>${cards().length} 张方法与案例卡</h2><p>从现有资料提炼输入、步骤、交付物和检查方法。摘要不是新实测，公开前仍需核对权限。</p></div>${badge('原知识库只读引用','teal')}</div><div class="tab-bar" aria-label="方法与案例分类">${['全部','真实案例','方法模板','内容方向'].map(v=>`<button data-action="distill-filter" data-value="${v}" aria-pressed="${filter===v}" class="${filter===v?'active':''}">${v}</button>`).join('')}</div><div class="distill-grid">${items.map(cardHTML).join('')}</div>${items.length?'':'<div class="empty-inline">还没有此类已核对的卡片。</div>'}<p class="quiet-note">${icon('info')}本轮经过独立草稿、交叉审查和来源核对。观点、案例记录和待验证建议分别标注；没有把多智能体同意当成业务效果证明。</p>`;}
    function details(c){const library=helpers.getLibrary();const related=[...(c.projectIds||[]).map(id=>{const p=library.projects.find(p=>p.id===id);return p?`<button class="small-button" data-action="real-project" data-id="${e(id)}">${e(p.title)}</button>`:'';}),...(c.workIds||[]).map(id=>{const w=library.works.find(w=>w.id===id);return w?`<button class="small-button" data-action="asset" data-id="${e(id)}">${e(w.title)}</button>`:'';}),...(c.knowledgeIds||[]).map(id=>{const k=library.knowledge.find(k=>k.id===id);return k?`<button class="small-button" data-action="library-record" data-kind="knowledge" data-id="${e(id)}">${e(k.title)}</button>`:'';})].filter(Boolean).join('');modal(c.title,`${badge(labels[c.kind],'blue')}<p class="dialog-lead">${e(c.summary)}</p><div class="distill-status">${e(c.status)}${c.observedAt?' · 资料核对 '+e(new Date(c.observedAt).toLocaleDateString('zh-CN',{timeZone:'America/Los_Angeles'})):''}</div><div class="detail-block"><h3>什么时候用</h3><p>${e(c.whenToUse)}</p><h3>先准备什么</h3><ul class="distill-list">${c.input.map(s=>`<li>${e(s)}</li>`).join('')}</ul><h3>可以怎样做</h3><ol class="distill-steps">${c.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol><h3>留下什么结果</h3><p>${e(c.output)}</p><h3>怎样检查</h3><ul class="distill-list">${c.acceptance.map(s=>`<li>${e(s)}</li>`).join('')}</ul></div><section class="distill-limits"><h3>适用边界</h3><ul>${c.limits.map(s=>`<li>${e(s)}</li>`).join('')}<li>${e(c.publicationStatus)}</li></ul></section><details class="distill-evidence"><summary>查看原始来源与关联资料</summary>${helpers.refsHTML(c.evidence)}${related?`<div class="distill-related">${related}</div>`:''}</details><div class="dialog-actions"><button class="outline-button" data-action="close">先看看</button><button class="primary-button" data-action="distill-task" data-id="${e(c.id)}">加入建议 ${c.nextAction.minutes} 分钟的小行动</button></div><p class="small-caption">只加入本地计划，不执行来源里的任务；建议时间不代表整个案例的完成耗时。</p>`,'方法与案例');}
    function handle(action,el){if(action==='distill-filter'){filter=el.dataset.value;ctx.render();return true;}if(action==='distill-open'){helpers.openTab();return true;}if(action==='distill-card'||action==='distill-task'){const c=cards().find(c=>c.id===el.dataset.id);if(!c){toast('这张卡片暂不可用，请重新核对本地资料');return true;}if(action==='distill-card')details(c);else helpers.addTask(c.nextAction.title,'来源卡片：'+c.title+'\n'+c.output+'\n适用边界：'+c.limits.join('；'),c.nextAction.minutes,{sourceCardId:c.id,evidence:c.acceptance.join('；')});return true;}return false;}
    function search(q){return cards().filter(c=>!q||(c.title+c.summary+c.whenToUse).toLowerCase().includes(q)).map(c=>({title:c.title,desc:c.summary,action:'distill-card',id:c.id,icon:'book-open'}));}
    return {render,handle,search};
  };
})();
